#include <cstddef>
#include <iostream>
#include <memory_resource>
class CountingResource final : public std::pmr::memory_resource {
public:
    std::size_t bytes() const { return bytes_; }
private:
    std::size_t bytes_ = 0;
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        void* ptr = std::pmr::new_delete_resource()->allocate(bytes, alignment); bytes_ += bytes; return ptr;
    }
    void do_deallocate(void* ptr, std::size_t bytes, std::size_t alignment) override {
        std::pmr::new_delete_resource()->deallocate(ptr, bytes, alignment);
    }
    bool do_is_equal(const std::pmr::memory_resource& other) const noexcept override { return this == &other; }
};
int main() { CountingResource resource; { std::pmr::vector<int> values{&resource}; values.resize(100); } std::cout << "allocated bytes=" << resource.bytes() << '\n'; }
